INSERT INTO category (id, name, slug, description) VALUES
    (1, 'Oral Care', 'oral-care', 'Sonicare electric toothbrushes, brush heads and power flossers'),
    (2, 'Smart Lighting', 'smart-lighting', 'Philips Hue smart bulbs, light strips, lamps and bundles'),
    (3, 'Kitchen Appliances', 'kitchen-appliances', 'Airfryers, blenders and kitchen helpers'),
    (4, 'Coffee Machines', 'coffee-machines', 'Fully automatic espresso machines and coffee pod machines'),
    (5, 'Shaving & Grooming', 'shaving-grooming', 'Electric shavers, OneBlade and multigroom trimmers'),
    (6, 'Air Care', 'air-care', 'Air purifiers and humidifiers for a healthier home'),
    (7, 'Hair Care', 'hair-care', 'Hair dryers, straighteners and stylers'),
