INSERT INTO product (id, sku, name, description, brand, price, currency, category_id, active, created_at, updated_at, version) VALUES
    (1, 'PH-SONIC-9900', 'Philips Sonicare DiamondClean Prestige 9900 Electric Toothbrush', 'Premium sonic electric toothbrush with SenseIQ, removes up to 20x more plaque. Includes charging travel case.', 'Philips Sonicare', 329.99, 'EUR', 1, TRUE, '2024-01-01 09:00:00.000000', '2024-01-01 09:00:00.000000', 0),
    (2, 'PH-SONIC-4300', 'Philips Sonicare ProtectiveClean 4300 Electric Toothbrush', 'Sonic electric toothbrush with pressure sensor and BrushSync replacement reminder.', 'Philips Sonicare', 59.99, 'EUR', 1, TRUE, '2024-02-04 09:01:00.000000', '2024-02-04 09:01:00.000000', 0),
    (3, 'PH-SONIC-FLOSS3000', 'Philips Sonicare Power Flosser 3000', 'Cordless water flosser with Quad Stream technology for gentle cleaning between teeth.', 'Philips Sonicare', 79.99, 'EUR', 1, TRUE, '2024-03-07 09:02:00.000000', '2024-03-07 09:02:00.000000', 0),
    (4, 'PH-HUE-E27-START3', 'Philips Hue White and Color Ambiance E27 Starter Kit (3 bulbs + Bridge)', 'Smart LED starter kit with 16 million colours, Hue Bridge included, works with Alexa and Google Assistant.', 'Philips Hue', 169.99, 'EUR', 2, TRUE, '2024-04-10 09:03:00.000000', '2024-04-10 09:03:00.000000', 0),
    (5, 'PH-HUE-PLAYBAR2', 'Philips Hue Play Light Bar Double Pack', 'Smart backlight bars for TV and monitor entertainment lighting, syncs with games and music.', 'Philips Hue', 139.99, 'EUR', 2, TRUE, '2024-05-13 09:04:00.000000', '2024-05-13 09:04:00.000000', 0),
    (6, 'PH-HUE-GRAD55', 'Philips Hue Play Gradient Lightstrip 55 inch', 'Gradient TV lightstrip that mirrors on-screen colours with multiple colours at once.', 'Philips Hue', 199.99, 'EUR', 2, TRUE, '2024-06-16 09:05:00.000000', '2024-06-16 09:05:00.000000', 0),
    (7, 'PH-AIRF-HD9870', 'Philips Airfryer XXL Premium HD9870/20', 'Family size airfryer with Smart Sensing technology and fat removal, 7.3 litre capacity.', 'Philips', 299.99, 'EUR', 3, TRUE, '2024-07-19 09:06:00.000000', '2024-07-19 09:06:00.000000', 0),
    (8, 'PH-AIRF-HD9252', 'Philips Airfryer Essential HD9252/90', 'Compact airfryer with Rapid Air technology for crispy results with little or no oil.', 'Philips', 99.99, 'EUR', 3, TRUE, '2024-08-22 09:07:00.000000', '2024-08-22 09:07:00.000000', 0),
    (9, 'PH-BLEND-HR3760', 'Philips Series 7000 High Speed Blender HR3760/00', 'Powerful 1500 W blender with ProBlend Ultra technology for smoothies and crushed ice.', 'Philips', 179.99, 'EUR', 3, TRUE, '2024-09-25 09:08:00.000000', '2024-09-25 09:08:00.000000', 0),
    (10, 'PH-COFF-EP3246', 'Philips Series 3200 Fully Automatic Espresso Machine LatteGo EP3246/70', 'Bean-to-cup espresso machine with LatteGo milk system, 5 coffee varieties and Aroma Extract.', 'Philips', 549.99, 'EUR', 4, TRUE, '2024-10-28 09:09:00.000000', '2024-10-28 09:09:00.000000', 0),
    (11, 'PH-COFF-EP5447', 'Philips Series 5400 Fully Automatic Espresso Machine LatteGo EP5447/90', 'Bean-to-cup espresso machine with 12 coffee varieties, user profiles and colour display.', 'Philips', 799.99, 'EUR', 4, TRUE, '2024-11-03 09:10:00.000000', '2024-11-03 09:10:00.000000', 0),
    (12, 'PH-SENSEO-HD6553', 'Philips Senseo Original Plus Coffee Pod Machine HD6553/60', 'Coffee pod machine with Coffee Boost technology and intensity selection.', 'Philips Senseo', 89.99, 'EUR', 4, TRUE, '2024-12-06 09:11:00.000000', '2024-12-06 09:11:00.000000', 0),
    (13, 'PH-ONEBLADE-QP6550', 'Philips OneBlade Pro 360 Face + Body QP6550/15', 'Hybrid trimmer and shaver with 360 blade and 14-length precision comb for face and body.', 'Philips', 79.99, 'EUR', 5, TRUE, '2024-01-09 09:12:00.000000', '2024-01-09 09:12:00.000000', 0),
    (14, 'PH-SHAVER-SP9883', 'Philips Shaver S9000 Prestige SP9883/36', 'Premium wet and dry electric shaver with Nano Tech precision blades and SkinIQ.', 'Philips', 449.99, 'EUR', 5, TRUE, '2024-02-12 09:13:00.000000', '2024-02-12 09:13:00.000000', 0),
    (15, 'PH-TRIM-MG7920', 'Philips Multigroom Series 7000 18-in-1 MG7920/15', 'All-in-one trimmer for face, hair and body with self-sharpening steel blades.', 'Philips', 69.99, 'EUR', 5, TRUE, '2024-03-15 09:14:00.000000', '2024-03-15 09:14:00.000000', 0),
    (16, 'PH-AIRPUR-AC0850', 'Philips Air Purifier 800 Series AC0850/10', 'Compact air purifier with HEPA filter, removes 99.97 percent of allergens for rooms up to 49 m2.', 'Philips', 129.99, 'EUR', 6, TRUE, '2024-04-18 09:15:00.000000', '2024-04-18 09:15:00.000000', 0),
    (17, 'PH-AIRPUR-AC3033', 'Philips Air Purifier 3000i Series AC3033/10', 'Connected air purifier with real-time air quality feedback and app control for rooms up to 104 m2.', 'Philips', 449.99, 'EUR', 6, TRUE, '2024-05-21 09:16:00.000000', '2024-05-21 09:16:00.000000', 0),
    (18, 'PH-HAIR-BHD827', 'Philips Hair Dryer Series 8000 BHD827/00', '2300 W hair dryer with ThermoShield technology and ionic care for fast, gentle drying.', 'Philips', 99.99, 'EUR', 7, TRUE, '2024-06-24 09:17:00.000000', '2024-06-24 09:17:00.000000', 0),
    (19, 'PH-HUE-ULTIMATE', 'Philips Hue Ultimate Home Bundle', 'Whole-home smart lighting bundle: 40 colour bulbs, 6 gradient lightstrips, outdoor lights, 2 Bridges and Sync Box.', 'Philips Hue', 5499.00, 'EUR', 2, TRUE, '2024-07-27 09:18:00.000000', '2024-07-27 09:18:00.000000', 0),
    (20, 'PH-AVENT-SCF293', 'Philips Avent Microwave Steam Steriliser SCF293/00 (discontinued)', 'Discontinued microwave steriliser for baby bottles. Kept for order history; not sold anymore.', 'Philips Avent', 49.99, 'EUR', 8, FALSE, '2024-08-02 09:19:00.000000', '2024-08-02 09:19:00.000000', 0);
